#![allow(dead_code)]

//! `std::stoi` reproduced, including which exception it throws.
//!
//! `std::stoi(str)` runs `strtol(str.c_str(), &end, 10)` and then:
//!
//! * throws `std::invalid_argument` when `strtol` consumed nothing, and
//! * throws `std::out_of_range` when the result does not fit an `int`
//!   (or `strtol` itself set `ERANGE`).
//!
//! So leading whitespace is skipped, a sign is optional, parsing stops at the
//! first non-digit, and trailing garbage is ignored: `"12abc"` is 12, `"3.9"` is
//! 3, and `"0x10"` is 0.

/// Which C++ exception `std::stoi` would have thrown.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum StoiError {
    /// `std::invalid_argument`: no digits were consumed.
    InvalidArgument,
    /// `std::out_of_range`: the value does not fit an `int`.
    OutOfRange,
}

impl StoiError {
    /// The mangled-name-free exception type as libstdc++'s terminate handler
    /// prints it.
    pub fn exception_type(self) -> &'static str {
        match self {
            StoiError::InvalidArgument => "std::invalid_argument",
            StoiError::OutOfRange => "std::out_of_range",
        }
    }

    /// `what()` is just the function name for both of these.
    pub fn what(self) -> &'static str {
        "stoi"
    }
}

/// `isspace` in the "C" locale, which is what `strtol` skips.
fn is_c_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

/// Parse `bytes` as `std::stoi` would.
///
/// Takes bytes rather than `&str` because `argv` is not required to be UTF-8 and
/// `strtol` works on bytes.
pub fn stoi(bytes: &[u8]) -> Result<i32, StoiError> {
    let mut i = 0;
    while i < bytes.len() && is_c_space(bytes[i]) {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let digits_start = i;
    // Accumulate in i64 (the width of `long` on this platform) and stop growing
    // once saturated: strtol clamps and sets ERANGE, and either way stoi throws.
    let mut magnitude: i64 = 0;
    let mut saturated = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = i64::from(bytes[i] - b'0');
        if !saturated {
            match magnitude
                .checked_mul(10)
                .and_then(|m| m.checked_add(digit))
            {
                Some(next) => magnitude = next,
                None => saturated = true,
            }
        }
        i += 1;
    }

    if i == digits_start {
        return Err(StoiError::InvalidArgument);
    }
    if saturated {
        return Err(StoiError::OutOfRange);
    }

    // -magnitude cannot overflow: magnitude is a non-negative i64 built from a
    // saturating accumulator, so it is at most i64::MAX.
    let value = if negative { -magnitude } else { magnitude };
    if value < i32::MIN as i64 || value > i32::MAX as i64 {
        return Err(StoiError::OutOfRange);
    }
    Ok(value as i32)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn parse(s: &str) -> Result<i32, StoiError> {
        stoi(s.as_bytes())
    }

    #[test]
    fn plain_numbers() {
        assert_eq!(parse("11"), Ok(11));
        assert_eq!(parse("0"), Ok(0));
        assert_eq!(parse("007"), Ok(7));
        assert_eq!(parse("+7"), Ok(7));
        assert_eq!(parse("-5"), Ok(-5));
        assert_eq!(parse("-0"), Ok(0));
        assert_eq!(parse("0000000000000000000000000000012"), Ok(12));
    }

    #[test]
    fn leading_whitespace_is_skipped_and_trailing_garbage_ignored() {
        assert_eq!(parse(" 12"), Ok(12));
        assert_eq!(parse("  \t\n\u{b}\u{c}\r +42xyz"), Ok(42));
        assert_eq!(parse("12abc"), Ok(12));
        assert_eq!(parse("3.9"), Ok(3));
        assert_eq!(parse("0x10"), Ok(0)); // base 10: "0", then 'x' stops it
    }

    #[test]
    fn no_digits_is_invalid_argument() {
        assert_eq!(parse(""), Err(StoiError::InvalidArgument));
        assert_eq!(parse("abc"), Err(StoiError::InvalidArgument));
        assert_eq!(parse("-"), Err(StoiError::InvalidArgument));
        assert_eq!(parse("+"), Err(StoiError::InvalidArgument));
        assert_eq!(parse("   "), Err(StoiError::InvalidArgument));
        assert_eq!(parse(" - 5"), Err(StoiError::InvalidArgument));
        // Whitespace is only skipped before the sign, never after it.
        assert_eq!(parse("\u{a0}5"), Err(StoiError::InvalidArgument));
    }

    #[test]
    fn int_boundaries() {
        assert_eq!(parse("2147483647"), Ok(i32::MAX));
        assert_eq!(parse("-2147483648"), Ok(i32::MIN));
        assert_eq!(parse("2147483648"), Err(StoiError::OutOfRange));
        assert_eq!(parse("-2147483649"), Err(StoiError::OutOfRange));
        assert_eq!(parse("9223372036854775808"), Err(StoiError::OutOfRange));
        assert_eq!(parse("99999999999999999999"), Err(StoiError::OutOfRange));
        // Saturating early must not wrap back into range.
        assert_eq!(
            parse("999999999999999999999999999999999999"),
            Err(StoiError::OutOfRange)
        );
    }
}
