//! The `terminate called after throwing an instance of ...` path.
//!
//! `main` in the C++ program does not catch anything, so an escaping exception
//! reaches `std::terminate`; libstdc++'s default handler prints the exception's
//! dynamic type and `what()` to stderr and then calls `abort()`, which kills the
//! process with `SIGABRT` (shell status 134).

use std::io::Write;

/// Print libstdc++'s verbose terminate message and abort, exactly as an uncaught
/// exception would.
pub fn terminate_after_uncaught_exception(exception_type: &str, what: &str) -> ! {
    let mut stderr = std::io::stderr();
    // Written as one buffer so it cannot interleave, and flushed explicitly
    // because abort() will not unwind or run any cleanup.
    let _ = write!(
        stderr,
        "terminate called after throwing an instance of '{exception_type}'\n  what():  {what}\n"
    );
    let _ = stderr.flush();
    std::process::abort()
}
